#include <stdio.h>
#include <stdint.h>

int main(void) {
    long long w, h, c;
    scanf("%lld %lld %lld", &w, &h, &c);
    size_t bytes = (size_t)w * (size_t)h * (size_t)c * sizeof(uint8_t);
    printf("%zu %.2f\n", bytes, bytes / (1024.0 * 1024.0));
    return 0;
}

